-- id:       fts-keyword
-- title:    Full-text search: "water leak"
-- concept:  tsvector @@ websearch_to_tsquery + ts_rank
-- rubric:   8 · Full-text search
-- purpose:  Keyword search over the generated search_tsv column with a GIN index. Compare with semantic search in the Vector Console.
-- GENERATED by web/scripts/export-queries.ts from src/lib/data/mock/lab.ts. Edit there, then run npm run db:queries.

SELECT complaint_id, title,
       ROUND(ts_rank(search_tsv, q)::numeric, 3) AS rank
FROM complaint, websearch_to_tsquery('english', 'water leak') AS q
WHERE search_tsv @@ q
ORDER BY rank DESC
LIMIT 10;
